package com.highpass.runspot.chat.outbox;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.LocalDateTime;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.PageRequest;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component @RequiredArgsConstructor public class ChatOutboxPublisher{private final ChatOutboxRepository repository;private final ChatRabbitPublisher rabbit;private final ObjectMapper mapper;
 @Scheduled(fixedDelayString="${chat.outbox.publish-delay-ms:1000}")@Transactional public void publish(){for(ChatOutbox outbox:repository.findReady(OutboxStatus.PENDING,LocalDateTime.now(),PageRequest.of(0,50))){try{String event=mapper.writeValueAsString(new ChatBrokerEvent(outbox.getId(),outbox.getDestination(),outbox.getPayload()));rabbit.publishConfirmed(event);outbox.published();}catch(Exception e){outbox.failed();}}}}
